INSERT INTO reports (cutoff,source,executive_summary,headers) VALUES ('2026-09-23','Dashboard_KSEC_CBS.xlsx','El corte registra 297 trabajadores y 2356 exigencias documentales. La aprobación global es 47.8%. La aprobación varió -0.4 puntos porcentuales respecto del corte anterior. Los documentos en estado Cargado aumentaron en 156, quedando 161 pendientes de aprobación. La dotación varió en -3 trabajadores. No existen trabajadores con todos sus documentos aprobados; 152 paquetes están incompletos y 79 presentan al menos un rechazo. Hay 19 documentos aprobados vencidos.','{"contractors": ["Contratista", "Trabajadores", "Documentos", "Aprobados", "No cargados", "Rechazados", "Cargados", "% aprobación", "Paquetes completos", "Paquetes incompletos", "Paquetes con rechazo", "Pendientes revisión", "Aprobados vencidos", "Vencen ≤30 días", "Tipos docs", "Documentos exigidos"], "packages": ["Contratista", "RUT", "Trabajador", "Estado trabajador", "Docs exigidos", "Aprobados", "No cargados", "Rechazados", "Cargados", "% aprobación", "Estado paquete (calculado)", "Aprobados vencidos", "Vencen ≤30 días", "Prioridad"], "gaps": ["Contratista", "RUT", "Trabajador", "Código documento", "Estado documento", "Fecha carga", "Fecha expiración", "Aprobado vencido", "Vence ≤30 días", "Comentario KSEC", "Archivo origen", "Fila", "Acción sugerida"], "history": ["Fecha corte", "Contratistas", "Trabajadores", "Documentos", "Aprobados", "% aprobación", "No cargados", "Rechazados", "Cargados", "Paquetes completos", "Paquetes incompletos", "Paquetes con rechazo", "Pendientes revisión", "Aprobados vencidos", "Vencen ≤30 días"], "documents": ["Contratista", "Fecha corte", "Hora consulta", "Archivo origen", "Fila origen", "RUT", "Trabajador", "Función / actividad", "Estado trabajador", "Código documento", "Estado documento", "Fecha carga", "Fecha expiración", "Comentarios", "Aprobado vencido", "Vence en 30 días"], "sources": ["Contratista", "Archivo", "Hora consulta KSEC", "Filas válidas", "Estado", "Observación"], "criteria": ["Criterio", "Definición"]}') ON CONFLICT (cutoff) DO NOTHING;
